// Galáxia Encantada scenes. Behaviour is keyed by SceneId, never by an image path. Asset data (sizes, poses, anchors)
// is generated by scripts/build-galaxia-assets.mjs into src/data/galaxia/<scene>.json.
import earthObservatory from "@/data/galaxia/earth-observatory.json";
import niveora from "@/data/galaxia/niveora.json";
import marsLab from "@/data/galaxia/mars-lab.json";
import lumina from "@/data/galaxia/lumina.json";
import layout from "@/data/galaxia/layout.json";

export type SceneId = "earth-observatory" | "niveora" | "mars-lab" | "lumina" | "earth-orbit" | "aurelia" | "red-tide";

export type Sprite = { src: string; w: number; h: number; feetX?: number };
type SceneAssets = { scene: string; background: Sprite; actors: Record<string, Record<string, Sprite>>; props: Record<string, Sprite> };
// Stages, prop scales and the pixel grid live in layout.json, shared with scripts/build-galaxia-assets.mjs.
type Layout = { grid: number; stages: Record<string, Stage>; props: Record<string, number> };
// Where an actor stands on the plate (percent) and how tall its reference pose is (percent of the plate height).
type Stage = { x: number; y: number; height: number; reference: string };

export type SceneDefinition = {
  id: SceneId;
  assets: SceneAssets;
  palette: { base: string; accent: string; glow: string };
  focalPoint: { x: number; y: number };
  stages: Record<string, Stage>;
  propScale: Record<string, number>;
};

export const SCENES = {
  "earth-observatory": {
    id: "earth-observatory",
    assets: earthObservatory,
    palette: { base: "#0b0a24", accent: "#6ff2d0", glow: "#ff8fd8" },
    focalPoint: { x: 78, y: 70 },
    stages: layout["earth-observatory"].stages as Layout["stages"],
    propScale: layout["earth-observatory"].props,
  },
  niveora: {
    id: "niveora",
    assets: niveora,
    palette: { base: "#0d2342", accent: "#55e9e8", glow: "#b89dfc" },
    focalPoint: { x: 80, y: 72 },
    stages: layout.niveora.stages as Layout["stages"],
    propScale: layout.niveora.props as Layout["props"],
  },
  "mars-lab": {
    id: "mars-lab",
    assets: marsLab,
    palette: { base: "#743a31", accent: "#42cfe0", glow: "#f3ae62" },
    focalPoint: { x: 80, y: 70 },
    stages: layout["mars-lab"].stages as Layout["stages"],
    propScale: layout["mars-lab"].props as Layout["props"],
  },
  lumina: {
    id: "lumina",
    assets: lumina,
    palette: { base: "#221435", accent: "#53e0e8", glow: "#e474c7" },
    focalPoint: { x: 82, y: 70 },
    stages: layout.lumina.stages as Layout["stages"],
    propScale: layout.lumina.props as Layout["props"],
  },
} satisfies Partial<Record<SceneId, SceneDefinition>>;

export type Box = { left: number; top: number; width: number; height: number };
const round = (value: number) => Math.round(value * 1000) / 1000;

// Percent box of a pose on the plate, standing on the stage's anchor: every pose shares the reference pose's scale.
export function poseBox(scene: SceneDefinition, actor: string, pose: string): Box {
  const { background, actors } = scene.assets;
  const stage = scene.stages[actor];
  const sprite = actors[actor][pose];
  const scale = stage.height / 100 * background.h / actors[actor][stage.reference].h;
  const width = sprite.w * scale / background.w * 100;
  const height = sprite.h * scale / background.h * 100;
  return { left: round(stage.x - (sprite.feetX ?? sprite.w / 2) * scale / background.w * 100), top: round(stage.y - height), width: round(width), height: round(height) };
}

// Props are drawn at the scale set in layout.json (the pixel art was cut for that size).
export function propBox(scene: SceneDefinition, prop: string, x: number, bottom: number, scale = scene.propScale[prop] ?? 1): Box {
  const { background, props } = scene.assets;
  const sprite = props[prop];
  const width = sprite.w * scale / background.w * 100;
  const height = sprite.h * scale / background.h * 100;
  return { left: round(x - width / 2), top: round(bottom - height), width: round(width), height: round(height) };
}

export const boxStyle = ({ left, top, width, height }: Box) => ({ left: `${left}%`, top: `${top}%`, width: `${width}%`, height: `${height}%` });
